import{_ as r,o as t,c as a,a5 as s}from"./chunks/framework.CslsFoWx.js";const n="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/01-ios-ipad-fr-clair-paiement-terminal.webp",i="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/02-ios-ipad-fr-clair-fenetre-code-vide.webp",o="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/03-ios-ipad-fr-clair-code-faux.webp",d="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/04-ios-ipad-fr-sombre-code-verrouille.webp",l="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/05-ios-ipad-ar-clair-fenetre-code.webp",c="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/06-ios-ipad-en-clair-fenetre-code.webp",u="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/07-ios-ipad-fr-clair-confirmation-apres-code.webp",p="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/08-ios-ipad-fr-clair-paiement-recu.webp",m="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/09-ios-ipad-ar-sombre-paiement-recu.webp",b="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/A1-ios-ipad-fr-clair-paiement-terminal-passerelle.webp",f="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/10-ios-iphone-fr-clair-alerte-a-enregistrer.webp",g="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/10-ios-ipad-fr-clair-alerte-a-enregistrer.webp",h="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/11-ios-iphone-fr-clair-liste-deja-payee.webp",v="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/12-ios-iphone-ar-clair-liste-deja-payee.webp",_="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/13-ios-iphone-fr-clair-addition-deja-payee.webp",y="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/14-ios-iphone-fr-sombre-addition-deja-payee.webp",q="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/15-ios-iphone-fr-clair-apres-enregistrement.webp",P="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/A2-ios-iphone-fr-sombre-derogation-stock.webp",S="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/D1-ios-iphone-fr-clair-erreur-rien-a-encaisser-apres-enregistrement.webp",k="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/16-bo-fr-clair-1280-paiements-a-enregistrer.webp",C="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/17-bo-ar-clair-1280-paiements-a-enregistrer.webp",V="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/18a-bo-fr-sombre-1280-paiements-a-enregistrer.webp",x="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/18b-bo-fr-sombre-390-paiements-a-enregistrer.webp",A="/VendoraSystem-docs/captures/2026-11-20-ven75-b2-borne/19-bo-fr-clair-1280-rapprochement-payee-a-enregistrer.webp",L=JSON.parse(`{"title":"VEN-75 vague B2 — borne à terminal autonome : code d'un responsable, paiement reçu à enregistrer — preuves sur le staging local (20/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-20-ven75-b2-borne.md","filePath":"generated/preuves/2026-11-20-ven75-b2-borne.md","lastUpdated":null}`),N={name:"preuves/2026-11-20-ven75-b2-borne.md"};function w(B,e,T,E,j,D){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="ven-75-vague-b2-—-borne-a-terminal-autonome-code-d-un-responsable-paiement-recu-a-enregistrer-—-preuves-sur-le-staging-local-20-11-2026" tabindex="-1">VEN-75 vague B2 — borne à terminal autonome : code d&#39;un responsable, paiement reçu à enregistrer — preuves sur le staging local (20/11/2026) <a class="header-anchor" href="#ven-75-vague-b2-—-borne-a-terminal-autonome-code-d-un-responsable-paiement-recu-a-enregistrer-—-preuves-sur-le-staging-local-20-11-2026" aria-label="Permalink to &quot;VEN-75 vague B2 — borne à terminal autonome : code d&#39;un responsable, paiement reçu à enregistrer — preuves sur le staging local (20/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-20-ven75-b2-borne</code> · 0 image(s) · 0 trace(s)</p><div><p>Ticket Linear VEN-75 (spec 09 RG-KIOSK, critères 23 et 24 de <code>docs/lots/VEN-75.md</code> ; écrans E1 à E4 de <code>docs/lots/VEN-75-B2-ecrans.md</code>).</p><p><strong>Résultat en bref : 22 captures iOS et back-office faites, TOUTES les captures Android manquent</strong> (émulateur inutilisable, voir « Ce qui manque »).</p><p><strong>Stack</strong> : staging local <code>http://localhost:8091</code> (images construites le 20/11 vers 12:10, <code>main</code> à la vague B2, migrations jusqu&#39;à V134), commerce fictif « Le Petit Bistrot (démo) ». Apps construites depuis <code>main</code> à 13:55 (XCFramework <code>Shared</code> reconstruit, <code>xcodebuild</code> sur <code>iosApp/build/dd-b2cap</code>). Appareils : simulateurs iOS 26.2 créés pour la série (iPad Air 11&quot; M3 portrait 820 × 1180 pt @2x ; iPhone 17 Pro 402 × 874 pt @3x), supprimés à la fin. Back-office : Chrome headless sur <code>localhost:8091/kiosks</code> (1280 px × 1,25, ou 390 px × 2). Borne : préréglage « Borne entrée » réglé sur « payer sur le terminal » avec confirmation manuelle ; produit « Tarte du jour (démo) » suivi en stock (stock 0) et magasin interdisant le stock négatif pour provoquer « payé, vente impossible » (raison « Stock insuffisant au moment du paiement »). Les chiffres des codes ne sont jamais visibles (points) ; les codes de test sont lus dans un fichier hors dépôt.</p><p>Les captures du dossier sont annotées (cadres numérotés) ; les copies sans repères sont dans <code>sans-annotation/</code>. Sauf mention, iOS = iPad pour la borne, iPhone pour la caisse.</p><h2 id="borne-ipad-fr-clair-sauf-mention-—-critere-23-et-24" tabindex="-1">Borne (iPad, FR clair sauf mention) — critère 23 et 24 <a class="header-anchor" href="#borne-ipad-fr-clair-sauf-mention-—-critere-23-et-24" aria-label="Permalink to &quot;Borne (iPad, FR clair sauf mention) — critère 23 et 24&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle prouve</th></tr></thead><tbody><tr><td><img src="'+n+'" alt=""></td><td>N° 01. Écran de paiement : (1) « Payez 2,50 € sur le terminal… », (2) numéro de commande, (3) bouton <strong>J&#39;ai payé sur le terminal</strong> (nouveau libellé, plus de « Paiement effectué »), (4) Payer en caisse. Critère 23.</td></tr><tr><td><img src="'+i+'" alt=""></td><td>N° 02. Fenêtre « Confirmer le paiement au terminal » : (1) ligne pour le client « Appelez un membre de l&#39;équipe… », (2) numéro du ticket de carte (facultatif), (3) pavé à points (aucun clavier système), (4) Confirmer le paiement grisé tant que le code n&#39;a pas 4 chiffres. Critère 23.</td></tr><tr><td><img src="'+o+'" alt=""></td><td>N° 03 (clé). Référence A1B2C3 saisie, deux codes faux : (1) référence conservée, (2) points vidés, (3) « PIN incorrect — 3 essai(s) restant(s) ». Critère 23.</td></tr><tr><td><img src="'+d+'" alt=""></td><td>N° 04 (clé), thème sombre. Cinq échecs : (1) « Trop d&#39;essais : PIN manager verrouillé jusqu&#39;à 14:44 », (2) pavé grisé, (3) Confirmer grisé, seul Annuler reste actif. Critère 23.</td></tr><tr><td><img src="'+l+'" alt=""></td><td>N° 05. Fenêtre en arabe : textes en miroir, référence A1B2C3 en LTR, pavé 1-2-3 de gauche à droite, « تأكيد الدفع » à gauche (fin en RTL).</td></tr><tr><td><img src="'+c+'" alt=""></td><td>N° 06. Fenêtre en anglais, avec « Wrong PIN — 4 attempt(s) left » (le compteur est reparti à 5 après le code juste précédent).</td></tr><tr><td><img src="'+u+'" alt=""></td><td>N° 07. Après un code juste : « Merci ! », numéro K89-001, « Paiement effectué » ; la vente est scellée, l&#39;imprimante absente donne « Imprimante indisponible : notez votre numéro ». Critère 23.</td></tr><tr><td><img src="'+p+'" alt=""></td><td>N° 08 (clé). Payé mais vente impossible (stock) : « Votre paiement a bien été reçu, vous n&#39;avez rien à repayer. Présentez ce numéro au comptoir… » + « J&#39;ai noté mon numéro », aucun « payez ». Critère 24.</td></tr><tr><td><img src="'+m+'" alt=""></td><td>N° 09. Même écran en arabe, thème sombre (numéro K89-003 isolé en LTR). Critère 24.</td></tr><tr><td><img src="'+b+'" alt=""></td><td>Extra. Même écran que 01 avec la passerelle simulée active : ligne « La borne continue dès que le terminal confirme le paiement ». C&#39;est la version utilisée pour la capture d&#39;aide <code>04-payez-sur-le-terminal</code>.</td></tr></tbody></table><p>Le chemin « webhook du terminal » (passerelle simulée, paiement simulé du back-office sur la commande K89-006) a produit le même écran 08 : les deux chemins de E2 aboutissent au même écran.</p><h2 id="caisse-ios-iphone-l-alerte-aussi-sur-ipad-—-critere-24" tabindex="-1">Caisse (iOS, iPhone ; l&#39;alerte aussi sur iPad) — critère 24 <a class="header-anchor" href="#caisse-ios-iphone-l-alerte-aussi-sur-ipad-—-critere-24" aria-label="Permalink to &quot;Caisse (iOS, iPhone ; l&#39;alerte aussi sur iPad) — critère 24&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle prouve</th></tr></thead><tbody><tr><td><img src="'+f+'" alt=""> <img src="'+g+'" alt=""></td><td>N° 10 (iPhone puis iPad). Alerte d&#39;avertissement non fermable sous la barre : « 3 commandes de borne déjà payées à enregistrer » + Voir.</td></tr><tr><td><img src="'+h+'" alt=""></td><td>N° 11. « Commandes kiosque à encaisser » : (1) commande déjà payée en tête, (2) badge « Déjà payée au terminal » sur sa propre ligne, chevron et aucun bouton « Payer ».</td></tr><tr><td><img src="'+v+'" alt=""></td><td>N° 12. Même liste en arabe : numéro, heure et montant isolés, badge « مدفوع مسبقاً عبر جهاز الدفع ».</td></tr><tr><td><img src="'+_+'" alt=""></td><td>N° 13 (clé). Addition K89-003 : (1) bandeau « Déjà payée au terminal de la borne — Ne faites pas repayer le client… (réf. TPE9Z81) », (2) bouton unique « Enregistrer le paiement carte · 6,50 € ».</td></tr><tr><td><img src="'+y+'" alt=""></td><td>N° 14. Même addition en sombre : bandeau lisible (texte clair sur fond brun).</td></tr><tr><td><img src="'+q+'" alt=""></td><td>N° 15. Après avoir enregistré les trois paiements : l&#39;alerte a disparu de l&#39;écran de vente (cadre = son emplacement). Limite : la capture du toast/confirmation en clair manque, voir le défaut D1.</td></tr><tr><td><img src="'+P+'" alt=""></td><td>Extra. Quand le magasin interdit le stock négatif, enregistrer la commande payée demande la dérogation « Vente au-delà du stock — approbation requise d&#39;un manager » (PIN + motif) : comportement documenté par l&#39;aide.</td></tr><tr><td><img src="'+S+'" alt=""></td><td>Défaut D1 (voir plus bas).</td></tr></tbody></table><h2 id="back-office-kiosks" tabindex="-1">Back-office (<code>/kiosks</code>) <a class="header-anchor" href="#back-office-kiosks" aria-label="Permalink to &quot;Back-office (`/kiosks`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle prouve</th></tr></thead><tbody><tr><td><img src="'+k+'" alt=""></td><td>N° 16. À 1 280 px : (1) tuile « À enregistrer en caisse » = 2, (2) bandeau d&#39;explication, (3) tableau : commande, borne, montant, transaction du terminal (+ « Confirmé à la main par un responsable »), raison « Stock insuffisant au moment du paiement », heure.</td></tr><tr><td><img src="'+C+'" alt=""></td><td>N° 17. Même section en arabe (page en miroir).</td></tr><tr><td><img src="'+V+'" alt=""> <img src="'+x+'" alt=""></td><td>N° 18. Thème sombre à 1 280 px, puis à 390 px : le tableau défile horizontalement dans son conteneur (1 : bandeau, 2 : tableau).</td></tr><tr><td><img src="'+A+'" alt=""></td><td>N° 19. Rapprochement du terminal (passerelle simulée active, « Rapprocher maintenant ») : la ligne <strong>« Payée, vente à enregistrer »</strong> (transaction SIMTPE-…, raison « Stock insuffisant ») apparaît avant la ligne « Confirmée, absente du relevé ». Le secret de la passerelle est masqué.</td></tr></tbody></table><h2 id="capture-d-aide-refaite" tabindex="-1">Capture d&#39;aide refaite <a class="header-anchor" href="#capture-d-aide-refaite" aria-label="Permalink to &quot;Capture d&#39;aide refaite&quot;">​</a></h2><p><code>help/public/captures/borne/paiement-borne/04-payez-sur-le-terminal.webp</code> : même écran, même format (900 px de large, iPad Air 11&quot; portrait), mêmes quatre repères, mais avec le libellé « J&#39;ai payé sur le terminal » ; montant 6,50 € et commande K89-006 (alt et légende mis à jour dans les trois langues). Copie sans repères : <code>sans-annotation/aide-04-payez-sur-le-terminal-passerelle.webp</code>.</p><h2 id="ce-qui-manque" tabindex="-1">Ce qui manque <a class="header-anchor" href="#ce-qui-manque" aria-label="Permalink to &quot;Ce qui manque&quot;">​</a></h2><ul><li><strong>Toutes les captures Android</strong> (borne sur tablette 01 à 09 ; caisse téléphone et tablette 10 à 15). Cause : la machine de développement était saturée par d&#39;autres sessions (moyenne de charge de 150 à 880, 1 800 à 2 300 processus). L&#39;émulateur « Aide_Tablette » a affiché à répétition « System UI isn&#39;t responding » puis « POS isn&#39;t responding » ; une capture d&#39;écran adb prenait 11 s à charge 50, et la borne revient à l&#39;accueil après 60 s d&#39;inactivité, ce qui rend la saisie de la référence et du code irréalisable. La borne Android a pu être appairée et l&#39;écran de paiement obtenu (« J&#39;ai payé sur le terminal », K16-001), mais la fenêtre du code n&#39;a pas pu être photographiée proprement. Les appareils Android et l&#39;émulateur ont été éteints/révoqués. À refaire quand la machine est calme (tablette puis téléphone), mêmes scénarios que ci-dessus.</li><li>Le toast / l&#39;écran « Vente enregistrée » en clair (15) : voir D1.</li><li>04 et 15 sont en sombre ou sans toast respectivement ; 11 ne montre que des commandes payées (aucune commande ordinaire n&#39;était en attente, la commande « K89-002 » avait expiré).</li></ul><h2 id="defauts-d-affichage-et-de-comportement-remarques" tabindex="-1">Défauts d&#39;affichage et de comportement remarqués <a class="header-anchor" href="#defauts-d-affichage-et-de-comportement-remarques" aria-label="Permalink to &quot;Défauts d&#39;affichage et de comportement remarqués&quot;">​</a></h2><ul><li><strong>D1 (iOS caisse, vrai défaut probable)</strong> : après « Enregistrer le paiement carte », la vente est bien enregistrée (n° fiscal attribué, commande retirée de la liste et du back-office), mais une feuille « Rien à encaisser : l&#39;addition est déjà réglée. » (bandeau danger + Fermer) s&#39;affiche par-dessus l&#39;écran « Vente enregistrée ». Observé 3 fois sur 3 (K89-003, K89-004, K89-006), en clair et en sombre. Cela ressemble à un second appel de <code>pay</code> après le succès. Capture D1.</li><li><strong>D2 (iOS borne iPad)</strong> : le libellé « Confirmer le paiement » passe sur deux lignes dans le bouton (fenêtre du code), en FR comme en sombre ; le champ du numéro de ticket reste noir pur en thème sombre (incohérent avec le reste de la fenêtre).</li><li><strong>D3 (iOS borne)</strong> : « PIN incorrect — 3 essai(s) restant(s) » : le « (s) » littéral est affiché au client/responsable (la fiche d&#39;écrans voulait un pluriel par fonction côté caisse ; la borne le garde).</li><li><strong>D4 (iOS caisse iPhone)</strong> : en-tête tronqué (« Le Petit Bistro… », « Sophie (manager) · … ») ; sur l&#39;addition payée au terminal, la pastille de statut « Addition demandée » est tronquée (« Addition deman… ») et ne devrait pas apparaître sur une commande déjà payée ; le bouton « Enregistrer le paiement carte · 6,50 € » passe sur deux lignes.</li><li><strong>D5 (parité, à vérifier sur Android quand possible)</strong> : sur la tablette Android, l&#39;écran de paiement affiche « La borne continue dès que le terminal confirme le paiement » alors que la passerelle simulée est désactivée ; sur iOS cette ligne n&#39;apparaît que passerelle active. Sur la fenêtre du code Android (tablette 1600 × 1000), la dernière rangée du pavé (0 et effacer) est coupée par le bas de la fenêtre.</li><li><strong>D6 (iOS borne)</strong> : l&#39;écran « Imprimante indisponible : notez votre numéro » apparaît en orange sur fond clair (texte d&#39;avertissement, contraste faible) sur la confirmation 07.</li></ul><h2 id="donnees-creees-ou-modifiees-sur-le-staging-local" tabindex="-1">Données créées ou modifiées sur le staging local <a class="header-anchor" href="#donnees-creees-ou-modifiees-sur-le-staging-local" aria-label="Permalink to &quot;Données créées ou modifiées sur le staging local&quot;">​</a></h2><ul><li>Préréglage « Borne entrée » : <code>PAY_AT_COUNTER</code>/confirmation manuelle non → <code>PAY_AT_TERMINAL</code>/oui pendant la série, <strong>remis à l&#39;état d&#39;origine</strong> (la version est passée de 1 à 4).</li><li>Politique de vente du magasin : <code>allowNegativeStock</code> mis à <code>false</code> pendant la série puis <strong>remis à <code>true</code></strong> (la politique n&#39;était pas publiée ; elle l&#39;est maintenant, aux valeurs par défaut, version 4).</li><li>Produit « Tarte du jour (démo) » (suivi en stock, 6,50 €) créé puis <strong>désactivé</strong>.</li><li>Commandes de borne : K89-001 (vente réelle de 2,50 €, scellée), K89-002 et K89-005 (non payées, expirées), K89-003, K89-004, K89-006 (payées au terminal, enregistrées en caisse : 3 ventes de 6,50 € scellées par l&#39;appareil iPhone), K16-001 (Android, non payée). Elles s&#39;ajoutent aux ventes scellées du Petit Bistrot ; à prévoir pour un contrôle d&#39;intégrité.</li><li>Passerelle du terminal : activée puis désactivée (son secret a été généré, jamais copié ; l&#39;état « jamais configurée » ne peut pas être rétabli) ; un rapprochement du 20/11 a été enregistré avec le bouton « Rapprocher maintenant » ; un paiement simulé (SIMTPE-…) a été reçu.</li><li>Appareils : bornes « Borne » (iPad) et « BorneAndroid », caisses « Caisse » (iPad) et « iPhone » créées puis révoquées. <strong>« Caisse Android » (appairée le matin par la série B1 à l&#39;émulateur dont j&#39;ai effacé les données) a été révoquée</strong> pour libérer une place (limite de 3 appareils de vente de la formule Restaurant) ; « Caisse iPhone » et « Caisse comptoir (démo) » n&#39;ont pas été touchés.</li></ul></div>',3)])])}const O=r(N,[["render",w]]);export{L as __pageData,O as default};
